function generate(rand, size) {
  const deptNames = ['IT', 'Sales', 'HR', 'Ops'];
  const names = ['Joe', 'Jim', 'Henry', 'Sam', 'Max', 'Ana', 'Lee', 'Kim'];
  const small = size === 'small';
  const deptCount = small ? Math.floor(rand() * 4) : 25;
  const Department = [];
  for (let id = 1; id <= deptCount; id++) Department.push([id, small ? deptNames[id - 1] : `Dept${id}`]);
  const Employee = [];
  if (deptCount > 0) {
    const count = small ? Math.floor(rand() * 9) : 2000;
    // Few salary levels make ties for the top common; departments share levels so equal salaries cross departments.
    const levels = small ? [100, 200, 300, 400] : Array.from({ length: 30 }, (_, i) => 1000 * (i + 1));
    for (let id = 1; id <= count; id++) {
      const name = small ? names[Math.floor(rand() * names.length)] : `Emp${id}`;
      Employee.push([id, name, levels[Math.floor(rand() * levels.length)], 1 + Math.floor(rand() * deptCount)]);
    }
  }
  return [{ Employee, Department }];
}
